/* DevOps lab topics. One short command per step, easiest first.
   Level 1 = Basic, Level 2 = Next level, Level 3 = Medium.
   step = [what you do, the command, output check (regex), why / interview note]
   A step passes only when its output matches the check. OK = "ran without an error message".
   Sample files used by the steps live in /scripts/lab-files (ready-made, so commands stay short). */

const OK = /^(?![\s\S]*(No such file|cannot |can't |Permission denied|command not found|not found|invalid|Unknown|Unable|failed|ERROR|Error|E: ))/;
const NOERR = /^(?![sS]*E: )/;   // apt: only a hard error fails (offline warnings are fine if the tool is already installed)
const LINE = w => new RegExp("(^|[\\r\\n])" + w + "[\\r\\n]");   // the whole output line is exactly w

const LAB = [

/* ================================================= 1 · LINUX ================================================= */
{ id: "t1", name: "1 · Linux", port: 7683, cwd: "~/lab",
  goal: "The commands every Linux interview starts with: files and folders first, then searching, permissions, disk and processes, then users, links and archives.",
  reset: ["cd ~", "rm -rf ~/lab", "userdel dev1"],
  levels: [
  { key: "l1", name: "Level 1 · Basic", steps: [
    ["Make a practice folder", "mkdir -p ~/lab", OK, "mkdir makes a folder. -p means no error if it already exists. ~ is your home folder. All practice stays inside ~/lab, so nothing else is touched."],
    ["Go into it", "cd ~/lab", OK, "cd = change directory. cd alone goes home, cd .. goes up one level, cd - goes back to the previous folder."],
    ["Where am I?", "pwd", LINE("\\/root\\/lab"), "pwd = print working directory: the full path of the folder you are in. Interview: 'how do you know where you are?'"],
    ["Who am I?", "whoami", LINE("root"), "Prints your user name. root is the all-powerful admin. On real servers you are a normal user and put sudo in front of admin commands."],
    ["Create an empty file", "touch a.txt", OK, "touch makes an empty file. If the file already exists it only updates its time."],
    ["List the files", "ls", /a\.txt/, "ls lists the folder. Common versions: ls -l (details), ls -a (also hidden files that start with a dot), ls -lh (sizes in KB/MB)."],
    ["Write a line into the file", "echo hello > a.txt", OK, "echo prints text. > sends it into a file and REPLACES what was there. >> adds to the end instead. Interview: 'difference between > and >>'."],
    ["Read the file", "cat a.txt", LINE("hello"), "cat prints the whole file. For long files use less (scroll, q to quit), head (first lines) or tail (last lines)."],
    ["Copy it", "cp a.txt b.txt", OK, "cp source destination. Add -r to copy a whole folder."],
    ["Make a folder", "mkdir notes", OK, "mkdir NAME makes one folder. With -p it also makes parent folders: mkdir -p a/b/c."],
    ["Move the copy into it", "mv b.txt notes", OK, "mv moves AND renames. mv old.txt new.txt renames. There is no separate rename command."],
    ["List with details", "ls -l", /drwx\S* .*notes/, "-l = long format: permissions, owner, group, size, date, name. First letter d = folder, - = file, l = link."],
    ["Delete a file", "rm a.txt", OK, "rm deletes for good, there is no recycle bin. Interview: 'what does rm -rf / do?' It wipes the system. Never run it."],
    ["Delete a folder", "rm -r notes", OK, "-r = recursive, needed for folders and everything inside. rmdir only removes EMPTY folders."],
    ["Date and time", "date", /\d{4}/, "Prints the current date and time of the machine. Logs use this clock, so a wrong clock confuses debugging."],
  ]},
  { key: "l2", name: "Level 2 · Next level", steps: [
    ["Copy a sample web log here", "cp /scripts/lab-files/access.log .", OK, "The dot means 'this folder'. The log has 8 lines: client IP, method, page, status code."],
    ["First lines of a file", "head -3 access.log", /10\.0\.0\.1 GET \/home 200/, "head shows the first lines (10 by default). The number after the dash sets how many."],
    ["Last lines of a file", "tail -2 access.log", /GET \/api 500/, "tail shows the last lines. tail -f FILE follows a log live as it grows, Ctrl+C stops. Interview: 'how do you watch a log in real time?'"],
    ["Count lines", "wc -l access.log", /8 access\.log/, "wc = word count. -l counts lines, -w words, -c bytes. Quick way to count requests or users."],
    ["Search inside a file", "grep 500 access.log", /GET \/api 500/, "grep prints the lines containing the text. Useful flags: -i ignore case, -v lines that do NOT match, -n show line numbers, -r search a whole folder."],
    ["Count the matches", "grep -c 200 access.log", LINE("5"), "-c prints how many lines matched: here 5 successful requests."],
    ["Find a file by name", "find . -name '*.log'", /\.\/access\.log/, "find WHERE -name PATTERN. Quotes stop the shell from expanding the *. Interview: find a file anywhere: find / -name nginx.conf"],
    ["Make the file private", "chmod 600 access.log", OK, "chmod changes permissions. Each digit is one group: owner, group, others. r=4, w=2, x=1, add them up. 6 = read+write, 0 = nothing."],
    ["Check the permissions", "ls -l access.log", /-rw-------/, "-rw------- = only the owner can read and write. Common values: 755 (programs, folders), 644 (normal files), 600 (private files), 700 (private folders)."],
    ["Disk space of the machine", "df -h", /Filesystem/, "df = disk free for each disk. -h = human sizes. Check Use% and 'Mounted on'. Interview: 'the disk is full, what is your first command?'"],
    ["Disk space of this folder", "du -sh .", /[0-9.]+[BKMG]?\s+\.[\r\n]/, "du = disk usage of files. -s = one total, -h = human sizes. df tells you WHICH disk is full, du tells you WHICH folder is eating it."],
    ["Memory", "free -m", /Mem:/, "free shows RAM in MB. Read the 'available' column, not 'free': Linux uses spare RAM as cache, so 'free' always looks small on a healthy machine."],
    ["List all processes", "ps aux", /USER\s+PID/, "ps aux = every running process with user, PID (process id), CPU%, memory% and command. You need the PID to stop a process."],
    ["Start a background process", "sleep 300 &", /\[\d+\] \d+/, "& runs the command in the background and gives your prompt back. It prints [job number] and the PID. sleep 300 simply waits 5 minutes."],
    ["Find its PID", "pgrep sleep", /(^|[\r\n])\d+[\r\n]/, "pgrep prints the PIDs of processes with that name. Same idea as ps aux | grep sleep, but shorter."],
    ["Stop it", "pkill sleep", OK, "pkill sends a polite stop signal (SIGTERM) by name. kill PID does it by number. kill -9 PID (SIGKILL) forces it when the polite one is ignored."],
  ]},
  { key: "l3", name: "Level 3 · Medium", steps: [
    ["Copy the log again", "cp /scripts/lab-files/access.log .", OK, "Every level starts from fresh files, so you can do the levels in any order."],
    ["Create a user", "useradd dev1", OK, "useradd makes an account. Real use: useradd -m -s /bin/bash NAME (-m makes a home folder, -s sets the shell). Accounts are stored in /etc/passwd."],
    ["Check the user", "id dev1", /uid=\d+\(dev1\)/, "id shows the user id (uid), main group (gid) and every group the user is in."],
    ["See the account line", "grep dev1 /etc/passwd", /(^|[\r\n])dev1:x:\d+:\d+/, "Colon separated: name, x (the password hash is in /etc/shadow), uid, gid, comment, home folder, shell."],
    ["Give admin rights", "usermod -aG sudo dev1", OK, "usermod changes a user. -aG = ADD to a group. Forgetting the -a REPLACES all their groups, a classic mistake. Members of the sudo group may run admin commands."],
    ["Check the groups", "groups dev1", /sudo/, "groups lists the groups of a user. dev1 now shows sudo."],
    ["Make a shortcut (soft link)", "ln -s /etc/hostname mylink", OK, "ln -s makes a symbolic link: a small file that points to another path. Without -s you get a hard link: a second name for the same data."],
    ["Check the link", "ls -l mylink", /mylink -> \/etc\/hostname/, "The arrow shows the target and the first letter l means link. Delete the target and a soft link breaks, a hard link keeps working."],
    ["Pack a file into an archive", "tar czf logs.tgz access.log", OK, "tar c = create, z = gzip compress, f = archive file name. Keep the letters together, then the archive name, then the files."],
    ["Look inside the archive", "tar tzf logs.tgz", /access\.log/, "t = list the contents without unpacking. To unpack: tar xzf logs.tgz (x = extract)."],
    ["Where does the shell look for programs?", "echo $PATH", /\/usr\/bin/, "$PATH is a list of folders separated by colons. When you type ls the shell searches them in order. 'command not found' means the program is in none of them."],
    ["Set an environment variable", "export APP=demo", OK, "export makes a variable visible to programs you start. Without export it stays inside your shell. To keep it after logout, add the line to ~/.bashrc."],
    ["Check it", "env | grep APP", /(^|[\r\n])APP=demo/, "env lists all environment variables. The pipe | sends env's output into grep, which keeps only the lines that match."],
    ["Is a package installed?", "dpkg -l curl", /ii\s+curl/, "dpkg -l NAME shows the package (ii = installed). Install with apt-get install NAME, remove with apt-get remove NAME."],
    ["Where is a command stored?", "which ls", /\/bin\/ls/, "which shows the full path of the program that would run. Useful when two versions are installed."],
    ["Is the machine busy?", "uptime", /load average/, "Shows how long the machine is up and the load average for 1, 5 and 15 minutes. If the load is higher than the number of CPU cores, the machine is overloaded."],
    ["Remove the user", "userdel dev1", OK, "userdel deletes the account (add -r to delete the home folder too)."],
  ]},
  ],
  server: { name: "On a real server", note: "Containers have no systemd, so these are copy-only. Run them on a real Linux server or a KodeKloud playground.", steps: [
    ["Is a service running?", "systemctl status nginx", null, "Shows active (running) or failed, plus the last log lines. First thing to check when a site is down."],
    ["Start, stop, restart", "systemctl restart nginx", null, "start / stop / restart / reload. reload re-reads the config without dropping connections."],
    ["Start at boot", "systemctl enable nginx", null, "enable = start automatically after a reboot. disable turns it off. enable --now does both enable and start."],
    ["Why did it fail? Read its logs", "journalctl -u nginx -n 30", null, "journalctl reads the system journal. -u = one service, -n 30 = last 30 lines, -f = follow live."],
    ["List failed services", "systemctl --failed", null, "Shows every service that crashed. Quick health check after a reboot."],
    ["Edit the schedule (cron)", "crontab -e", null, "Opens your cron table. A line looks like: */5 * * * * /home/me/backup.sh (minute hour day month weekday command)."],
    ["Edit sudo rules safely", "visudo", null, "Always edit /etc/sudoers with visudo. It checks the syntax before saving, a typo cannot lock you out."],
  ]},
  qa: [
    ["The disk is full. How do you find out why?", [["Step 1", "df -h shows which disk is full."], ["Step 2", "du -sh /var/* shows which folder is the biggest. Repeat one level deeper until you find it."], ["Also check", "df -i. A disk with free space can still be 'full' if all inodes (file slots) are used by millions of tiny files."]]],
    ["A process uses too much CPU. What do you do?", [["Find it", "top (press P to sort by CPU) or ps aux --sort=-%cpu | head."], ["Stop it", "kill PID first (polite). If it ignores that: kill -9 PID."], ["Then", "Find out WHY: check its logs, do not just keep killing it."]]],
    ["How do you find a file, and text inside files?", [["File by name", "find / -name nginx.conf"], ["Text inside files", "grep -r 'error' /var/log"], ["Tip", "Add 2>/dev/null to hide 'Permission denied' noise."]]],
    ["What do 755, 644 and 600 mean?", [["755", "rwxr-xr-x: owner full, everyone else read and run. For programs and folders."], ["644", "rw-r--r--: owner read and write, everyone else read. Normal files."], ["600", "rw-------: only the owner. Private keys (ssh refuses keys that are more open)."]]],
    ["Hard link vs soft (symbolic) link?", [["Soft", "ln -s target link. A pointer to a PATH. Breaks if the target is deleted. Can cross disks."], ["Hard", "ln target link. Another NAME for the same data. Survives deleting the original name."]]],
    ["What is the difference between >, >> and |?", [[">", "Sends output to a file and REPLACES it."], [">>", "Sends output to a file and ADDS to the end."], ["|", "Sends the output of one command into the next command."]]],
    ["How do you check CPU, memory and load?", [["CPU and processes", "top"], ["Memory", "free -m (read 'available')"], ["Load", "uptime (compare with the number of cores: nproc)"]]],
  ] },

/* ================================================= 2 · BASH ================================================= */
{ id: "t2", name: "2 · Bash scripting", port: 7683, cwd: "~/lab",
  goal: "From running a script and reading its exit code, to if and loops, to the log-analysis one-liners interviewers love. Pipes are built up one piece at a time.",
  reset: ["cd ~", "rm -rf ~/lab"],
  levels: [
  { key: "l1", name: "Level 1 · Basic", steps: [
    ["Make a practice folder", "mkdir -p ~/lab", OK, "All script practice happens in ~/lab."],
    ["Go into it", "cd ~/lab", OK, "cd = change directory."],
    ["Copy a ready-made script", "cp /scripts/lab-files/hello.sh .", OK, "The script has 3 lines. You will read it next."],
    ["Read the script", "cat hello.sh", /echo "Hello, \$name"/, "Line 1 #!/bin/bash (the shebang) says which program runs the file. Line 2 sets name to the first argument ($1), or 'world' if none. Line 3 prints it."],
    ["Look at its permissions", "ls -l hello.sh", /hello\.sh/, "The x in -rwxr-xr-x means 'may be executed'. A script without x cannot be started with ./script.sh."],
    ["Make it executable", "chmod +x hello.sh", OK, "+x adds the execute permission for everyone. Interview: 'I wrote a script and get Permission denied, why?' You forgot chmod +x."],
    ["Run it", "./hello.sh", /Hello, world/, "./ means 'in this folder'. Without it the shell only searches $PATH and says command not found."],
    ["Run it with an argument", "./hello.sh Asha", /Hello, Asha/, "Words after the script name are arguments. Inside the script the first is $1, the second $2, how many is $#, all of them is $@."],
    ["Run it with bash directly", "bash hello.sh Ravi", /Hello, Ravi/, "bash FILE runs the script without needing +x. Handy for a quick test."],
    ["Exit code of the last command", "echo $?", LINE("0"), "$? holds the exit code of the previous command. 0 = success, anything else = failure. Scripts and CI pipelines decide pass or fail from this number."],
    ["Set a variable", "name=Meera", OK, "NO spaces around =. name = Meera fails, because the shell thinks name is a command."],
    ["Use the variable", "echo $name", LINE("Meera"), "$name gives the value. Use quotes when it may contain spaces: echo \"$name\"."],
    ["Quotes: double expands, single does not", "echo \"Hello $name\"", /(^|[\r\n])Hello Meera/, "Double quotes expand variables. Single quotes print the text exactly as typed: echo 'Hello $name' prints Hello $name."],
  ]},
  { key: "l2", name: "Level 2 · Next level", steps: [
    ["Copy a script with an if", "cp /scripts/lab-files/check.sh .", OK, "check.sh tests whether the file given as the first argument exists."],
    ["Copy a script with a loop", "cp /scripts/lab-files/loop.sh .", OK, "loop.sh repeats a command three times."],
    ["Read the if script", "cat check.sh", /if \[ -f/, "if [ -f FILE ] is true when the file exists. Other tests: -d folder, -z empty text, -eq number equal. Spaces inside [ ] are required."],
    ["Test: the file exists", "bash check.sh hello.sh", /found hello\.sh/, "The if branch runs and prints found."],
    ["Test: the file is missing", "bash check.sh nothing.txt", /missing nothing\.txt/, "The else branch runs, and the script ends with exit 1 to tell the caller it failed."],
    ["Read the exit code", "echo $?", LINE("1"), "1 = the script failed on purpose. Without a final exit the script returns the exit code of its last command."],
    ["Run the loop", "bash loop.sh", /round 3/, "for i in 1 2 3 repeats the body once per value. Also common: while read line, and for f in *.log."],
    ["Copy a sample log", "cp /scripts/lab-files/access.log .", OK, "Columns: IP, method, page, status."],
    ["Pick one column", "cut -d' ' -f1 access.log", /10\.0\.0\.4/, "cut -d' ' sets the separator to a space, -f1 picks field 1 (the IP). Try -f4 for the status code."],
    ["Count the GET requests", "grep -c GET access.log", LINE("7"), "grep -c counts matching lines."],
    ["Lines that are NOT 200", "grep -v 200 access.log", /404/, "-v inverts the match: shows everything except 200. First thing to do when looking for failed requests."],
    ["Count all lines", "wc -l access.log", /8 access\.log/, "Total requests = number of lines."],
  ]},
  { key: "l3", name: "Level 3 · Medium", steps: [
    ["Copy the log again", "cp /scripts/lab-files/access.log .", OK, "Fresh start for this level."],
    ["Save the IP column to a file", "cut -d' ' -f1 access.log > ips.txt", OK, "> saves output into a file. Now ips.txt has one IP per line. Next we turn it into a 'top clients' list, one piece at a time."],
    ["Piece 1: sort", "sort ips.txt", /10\.0\.0\.4/, "sort puts identical lines next to each other. uniq only merges NEIGHBOURING lines, so you must sort first."],
    ["Piece 2: count the repeats", "sort ips.txt | uniq -c", /4 10\.0\.0\.1/, "uniq -c puts a count in front of each distinct line. 10.0.0.1 appears 4 times."],
    ["Piece 3: biggest first", "sort ips.txt | uniq -c | sort -rn", /(^|[\r\n])\s*4 10\.0\.0\.1[\r\n]/, "sort -rn = numeric, reverse. Add | head -3 for the top 3. This exact pipeline is a very common interview question."],
    ["awk: print the status column", "awk '{print $4}' access.log", LINE("404"), "awk splits each line into fields: $1 first column, $4 fourth, $NF last. print shows them."],
    ["awk: filter rows", "awk '$4 == 500' access.log", /GET \/api 500/, "Only the lines where column 4 equals 500. Server errors. Use $4 >= 500 for all 5xx."],
    ["sed: replace text", "sed 's/GET/get/' access.log", /10\.0\.0\.1 get \/home 200/, "sed 's/old/new/' replaces the first match on every line and prints the result. The file is NOT changed. Add -i to edit in place."],
    ["Copy the strict and loose scripts", "cp /scripts/lab-files/loose.sh .", OK, "loose.sh prints start, tries to read a missing file, then prints never printed."],
    ["Copy the strict script", "cp /scripts/lab-files/strict.sh .", OK, "strict.sh is the same script with one extra line: set -euo pipefail."],
    ["Run the loose script", "bash loose.sh", /(^|[\r\n])never printed/, "By default bash keeps going after an error, so 'never printed' IS printed. Dangerous in deploy scripts."],
    ["Run the strict script", "bash strict.sh", /^(?![\s\S]*never printed)[\s\S]*No such file/, "set -e stops at the first error, -u stops on an unset variable, -o pipefail fails a pipe if any part fails. Interview: 'what does set -euo pipefail do?'"],
    ["Copy a script with a function", "cp /scripts/lab-files/func.sh .", OK, "A function groups commands so you can reuse them."],
    ["Run it", "bash func.sh", /Hi Asha[\s\S]*Hi Ravi/, "greet Asha calls the function and Asha becomes $1 inside it."],
    ["Check syntax without running", "bash -n hello.sh", OK, "-n reads the script and reports syntax errors but runs nothing. No output means no syntax errors."],
  ]},
  ],
  server: { name: "Cron and background jobs", note: "Needs cron on a real server. Copy-only.", steps: [
    ["List your scheduled jobs", "crontab -l", null, "Shows the cron table of the current user."],
    ["Edit the schedule", "crontab -e", null, "Line format: minute hour day-of-month month day-of-week command. */5 * * * * = every 5 minutes. 0 2 * * * = every day at 02:00."],
    ["Log the output of a cron job", "0 2 * * * /home/me/backup.sh >> /var/log/backup.log 2>&1", null, ">> appends the output. 2>&1 sends errors into the same file. Without this, cron output is lost."],
    ["Keep a script running after logout", "nohup ./job.sh &", null, "nohup ignores the hangup signal when you close the terminal. & puts it in the background."],
    ["Debug a script", "bash -x script.sh", null, "-x prints every command before it runs. Best way to see where a script goes wrong."],
  ]},
  qa: [
    ["What does set -euo pipefail do?", [["-e", "Stop at the first command that fails."], ["-u", "Treat an unset variable as an error."], ["-o pipefail", "A pipeline fails if ANY command in it fails, not only the last."]]],
    ["What is an exit code?", [["Meaning", "A number every command returns. 0 = success, non-zero = failure."], ["Read it", "echo $? right after the command."], ["Use it", "if command; then ... fi, or command || exit 1."]]],
    ["Single quotes vs double quotes?", [["Double", "Variables and $(commands) are expanded."], ["Single", "Everything is literal text."]]],
    ["How do you pass and read arguments?", [["Read", "$1 $2 ... are the arguments, $# how many, $@ all of them, $0 the script name."]]],
    ["Find the IPs that hit the server most", [["Answer", "cut -d' ' -f1 access.log | sort | uniq -c | sort -rn | head"], ["Why sort first?", "uniq only merges neighbouring lines."]]],
    ["Read the cron schedule */15 9-17 * * 1-5", [["Meaning", "Every 15 minutes, between 09:00 and 17:59, Monday to Friday."], ["Order", "minute, hour, day of month, month, day of week."]]],
    ["Difference between ; && and ||?", [[";", "Run the next command always."], ["&&", "Run the next command only if the first SUCCEEDED."], ["||", "Run the next command only if the first FAILED."]]],
  ] },

/* ================================================= 3 · NETWORKING ================================================= */
{ id: "t3", name: "3 · Networking", port: 7683, cwd: "~/lab",
  goal: "From 'what is my IP' and ping, to DNS and open ports, to who is listening on a port. Everything in Levels 1-3 works offline. The last tab needs internet.",
  reset: ["cd ~", "pkill nc", "rm -rf ~/lab"],
  levels: [
  { key: "l1", name: "Level 1 · Basic", steps: [
    ["Setup: refresh the package list", "apt-get update -qq", NOERR, "Downloads the list of available packages. -qq = quiet. Needs internet the first time. Skip it if the tools below are already installed."],
    ["Setup: install the network tools", "apt-get install -y -qq iputils-ping dnsutils netcat-openbsd traceroute net-tools", NOERR, "ping, dig/nslookup, nc, traceroute and netstat are not in a minimal Ubuntu. -y answers yes for you."],
    ["Make a practice folder", "mkdir -p ~/lab", OK, "Keeps the practice in one place."],
    ["Name of this machine", "hostname", LINE("sshlab"), "The machine name. In scripts and logs it tells you which server you are on."],
    ["Show IP addresses", "ip addr", /inet 127\.0\.0\.1/, "ip addr (short: ip a) lists every network interface with its IP. lo = loopback (127.0.0.1, this machine itself), eth0 = the real network card. Older name: ifconfig."],
    ["Show the routes", "ip route", /default via/, "The routing table. 'default via X' = where packets go when no other rule matches: your gateway (router)."],
    ["Local name list", "cat /etc/hosts", /localhost/, "/etc/hosts maps names to IPs on this machine only. It is checked before DNS, so it is a quick way to override a name."],
    ["Which DNS server is used?", "cat /etc/resolv.conf", /nameserver/, "Lists the DNS servers this machine asks to turn names into IPs."],
    ["Ping this machine", "ping -c 2 127.0.0.1", /2 received/, "ping sends small test packets and times the answer. -c 2 = only two (otherwise it never stops, Ctrl+C ends it). 0% packet loss = reachable."],
    ["Is curl there?", "curl --version", /curl \d/, "curl is the tool for talking HTTP from the terminal. You will use it a lot: -I headers only, -s silent, -v details, -L follow redirects, -o save to a file."],
  ]},
  { key: "l2", name: "Level 2 · Next level", steps: [
    ["DNS lookup (easy output)", "nslookup example.com", /Address: \d+/, "nslookup asks DNS for the IP of a name. The first Address is the DNS server, the next ones are the answer."],
    ["DNS lookup (short answer)", "dig example.com +short", /(^|[\r\n])\d+\.\d+\.\d+\.\d+[\r\n]/, "dig is the admin's DNS tool. +short prints only the answer. Try dig example.com MX for mail servers and NS for name servers."],
    ["Name to IP on this machine", "getent hosts localhost", /localhost/, "getent uses the same lookup order as programs do: /etc/hosts first, then DNS."],
    ["Which ports are listening?", "ss -tln", /State/, "ss lists sockets. -t TCP, -l listening only, -n numbers (do not resolve names). Add -p to see the process. This replaces the older netstat."],
    ["Start a listener on port 9000", "nc -l 9000 &", /\[\d+\] \d+/, "nc (netcat) is the network Swiss army knife. -l waits for a connection. & keeps it in the background. We now have a tiny 'server' to test against."],
    ["Is it listening?", "ss -tln", /:9000/, "Port 9000 is in the list. This is how you prove a service is up."],
    ["Test the port", "nc -zv 127.0.0.1 9000", /succeeded/, "-z = just connect, -v = tell me the result. 'succeeded' = open. 'refused' = nothing listens. A hang = a firewall drops the packets."],
    ["Stop the listener", "pkill nc", OK, "Clean up the background process."],
  ]},
  { key: "l3", name: "Level 3 · Medium", steps: [
    ["Compact address list", "ip -br addr", /lo\s+(UNKNOWN|UP)/, "-br = brief, one line per interface with its state. Easy to read when there are many interfaces."],
    ["Interface details", "ip link", /LOOPBACK/, "Shows state (UP/DOWN), MTU and MAC address. A DOWN interface is the first thing to check when 'the network is dead'."],
    ["Socket summary", "ss -s", /Total:/, "How many TCP connections exist and in which state. Many TIME-WAIT or SYN-RECV entries can point to a problem."],
    ["Start a listener again", "nc -l 9000 &", /\[\d+\] \d+/, "A small server on port 9000."],
    ["Who owns the port?", "ss -tlnp", /users:\(\("nc"/, "-p adds the process that owns each port. Interview: 'what is using port 80?' Answer: ss -tlnp | grep :80 (or lsof -i :80)."],
    ["Connect to it", "nc -zv 127.0.0.1 9000", /succeeded/, "A successful port test. The same command against a real server tells you whether a firewall blocks the port."],
    ["Stop the listener", "pkill nc", OK, "Clean up."],
    ["Trace the path", "traceroute -m 3 127.0.0.1", /traceroute to/, "traceroute shows every router (hop) on the way to a target. -m 3 stops after 3 hops. Stars (* * *) mean a hop does not answer, not necessarily a failure. Here the target is this machine: one hop."],
  ]},
  { key: "net", name: "Needs internet (optional)", optional: true, steps: [
    ["Older command for open ports (needs net-tools)", "netstat -tln", /Proto/, "netstat shows the same list as ss. Interviewers still ask for it, so know both. It comes from the net-tools package installed in the setup step."],
    ["Ping the internet", "ping -c 2 8.8.8.8", /2 received/, "8.8.8.8 is Google's DNS. Works = you have internet by IP. Interview: 'ping works by IP but not by name' means DNS is broken."],
    ["Ping by name", "ping -c 2 example.com", /2 received/, "Needs DNS first, then the ping."],
    ["Fetch only the header", "curl -I https://example.com", /HTTP\/[\d.]+ 200/, "-I shows the response headers. 200 = OK, 301/302 = redirect, 404 = not found, 500 = server error."],
    ["Download the page", "curl -s https://example.com", /Example Domain/, "-s = silent, no progress bar. Add -L to follow redirects."],
    ["Is a remote port open?", "nc -zv example.com 443", /succeeded/, "Port 443 = HTTPS. 'succeeded' = reachable."],
    ["See the TLS handshake", "curl -sv https://example.com -o /dev/null", /TLSv1\.[23]/, "-v shows DNS, TCP connect, TLS version and certificate. This is how you debug HTTPS problems. -o /dev/null throws the page away."],
    ["Reverse DNS", "dig -x 8.8.8.8 +short", /dns\.google/, "-x turns an IP back into a name."],
    ["Trace the path to the internet", "traceroute -m 5 8.8.8.8", /traceroute to 8\.8\.8\.8/, "Each line is a router on the way."],
  ]},
  ],
  server: { name: "Firewall and packet capture", note: "Needs a real server with root access. Copy-only.", steps: [
    ["Firewall status (Ubuntu)", "ufw status", null, "ufw is the simple firewall front end. Shows allowed ports."],
    ["Allow SSH", "ufw allow 22/tcp", null, "Always allow SSH BEFORE you enable the firewall, or you lock yourself out. Then ufw allow 443/tcp and ufw enable."],
    ["Low-level firewall rules", "iptables -L -n", null, "Lists the real rules ufw writes. -n = numbers only (faster)."],
    ["Capture packets on port 80", "tcpdump -i any port 80 -c 10", null, "Shows 10 packets live. Used when you must prove whether traffic arrives at all."],
    ["SSH tunnel to a remote port", "ssh -L 8080:localhost:80 user@server", null, "Makes the server's port 80 appear as localhost:8080 on your machine."],
  ]},
  qa: [
    ["A website does not open. What do you check, in order?", [["1 Network", "ping the IP (8.8.8.8) - do I have internet?"], ["2 DNS", "nslookup the name - does it give an IP?"], ["3 Port", "nc -zv host 443 - is the port open?"], ["4 App", "curl -I https://host - what HTTP code comes back?"]]],
    ["What happens when you type a URL in the browser?", [["Short answer", "DNS finds the IP, TCP connects (3-way handshake), TLS sets up encryption for HTTPS, the browser sends an HTTP request, the server answers, the browser renders it."]]],
    ["Explain the TCP 3-way handshake", [["Steps", "SYN (client asks), SYN-ACK (server agrees), ACK (client confirms). Then data flows."]]],
    ["What does /24 mean (192.168.1.0/24)?", [["Meaning", "The first 24 bits are the network, the last 8 are hosts: 256 addresses (254 usable). /16 = 65,536, /32 = one address."]]],
    ["TCP vs UDP?", [["TCP", "Reliable, ordered, connection first. Web, SSH, databases."], ["UDP", "Fast, no guarantee. DNS lookups, video, games."]]],
    ["Connection refused vs timed out?", [["Refused", "The machine answered: nothing listens on that port (service down)."], ["Timed out", "No answer at all: firewall or wrong route."]]],
    ["Which process uses port 80?", [["Answer", "ss -tlnp | grep :80 (or lsof -i :80)."]]],
  ] },

/* ================================================= 4 · NGINX ================================================= */
{ id: "t4", name: "4 · NGINX", port: 7683, cwd: "~/lab",
  goal: "Install and start NGINX, serve a page, then reverse proxy, load balance and debug a 502. Config files are ready-made, so you only copy, test and reload. Uses its own ports (8000-8083).",
  reset: ["cd ~", "nginx -s stop", "rm -f /etc/nginx/conf.d/site.conf /etc/nginx/conf.d/lab.conf /etc/nginx/conf.d/lb.conf /etc/nginx/conf.d/bad.conf /etc/nginx/conf.d/routes.conf", "rm -rf /var/www/lab ~/lab"],
  levels: [
  { key: "l1", name: "Level 1 · Basic", steps: [
    ["Setup: refresh the package list", "apt-get update -qq", NOERR, "Refreshes the list of packages. Needs internet the first time. Skip it if NGINX is already installed."],
    ["Setup: install NGINX", "apt-get install -y -qq nginx", NOERR, "On a real server: sudo apt install nginx. It installs the program, the config in /etc/nginx and the logs in /var/log/nginx."],
    ["Which version?", "nginx -v", /nginx\/\d/, "Prints the version. -V (capital) also prints the build options and modules."],
    ["Copy a small site config", "cp /scripts/lab-files/site.conf /etc/nginx/conf.d/site.conf", OK, "site.conf says: listen on port 8000 and serve the files in /var/www/lab. Read it with cat. Every file in conf.d/ is included automatically."],
    ["Make the web folder", "mkdir -p /var/www/lab", OK, "The 'web root': the folder NGINX serves files from."],
    ["Create a home page", "echo 'My first site' > /var/www/lab/index.html", OK, "index.html is what NGINX shows for the path /."],
    ["Test the config", "nginx -t", /syntax is ok/, "ALWAYS run this before starting or reloading. It checks the syntax and does not touch the running server."],
    ["Start NGINX", "nginx", /^(?![\s\S]*(emerg|command not found))/, "Starts the server in the background. On a real server you use systemctl start nginx (a container has no systemd). If you see 'Address already in use', NGINX is already running: use nginx -s reload."],
    ["Open the page", "curl localhost:8000", /My first site/, "curl is the quickest way to test a web server from the terminal. Your page came from /var/www/lab."],
    ["Look at the response header", "curl -I localhost:8000", /HTTP\/1\.1 200 OK/, "200 OK. Other codes: 301 redirect, 403 no permission, 404 file not found, 502 backend problem."],
    ["Where is the config?", "ls /etc/nginx", /nginx\.conf/, "nginx.conf is the main file. conf.d/ holds extra files that are included automatically. sites-enabled/ holds site configs on Ubuntu."],
    ["Where are the logs?", "ls /var/log/nginx", /access\.log/, "access.log = every request. error.log = problems. When something breaks, read error.log first."],
    ["Read the last request", "tail -2 /var/log/nginx/access.log", /GET \/ HTTP/, "Each line: client IP, time, request, status code, bytes, browser. Your curl commands are in there."],
  ]},
  { key: "l2", name: "Level 2 · Next level", needs: "l1", steps: [
    ["Change the page", "echo 'Version 2' > /var/www/lab/index.html", OK, "Changing a FILE needs no reload. Only config changes do."],
    ["See the change", "curl localhost:8000", /Version 2/, "NGINX reads the file on every request."],
    ["Copy a reverse proxy config", "cp /scripts/lab-files/proxy.conf /etc/nginx/conf.d/lab.conf", OK, "proxy.conf has 2 servers: a 'backend' on port 9000 and a proxy on port 8080 that forwards to it. Read it with cat."],
    ["Test the config", "nginx -t", /syntax is ok/, "Syntax ok = safe to reload."],
    ["Reload without downtime", "nginx -s reload", OK, "-s reload applies the new config and keeps existing connections alive. On a real server: systemctl reload nginx. Restart drops connections, reload does not."],
    ["Call the backend directly", "curl localhost:9000", /backend ok/, "This is the application server (the 'upstream'). Normally users never reach it directly."],
    ["Call it through the proxy", "curl localhost:8080", /backend ok/, "Same answer, but NGINX forwarded the request with proxy_pass. A reverse proxy sits in front of apps and gives you TLS, caching, load balancing and one public entry point."],
    ["See the requests in the log", "tail -3 /var/log/nginx/access.log", /GET/, "Every request through NGINX is logged. First place to look when users report errors."],
  ]},
  { key: "l3", name: "Level 3 · Medium", needs: "l1", steps: [
    ["Copy a load balancer config", "cp /scripts/lab-files/lb.conf /etc/nginx/conf.d/lb.conf", OK, "lb.conf defines an upstream pool with 2 backends (ports 9001 and 9002) and a front server on port 8081."],
    ["Test the config", "nginx -t", /syntax is ok/, "Always test before reload."],
    ["Reload", "nginx -s reload", OK, "Applies lb.conf."],
    ["Request 1", "curl localhost:8081", /backend [12]/, "The answer says which backend served you."],
    ["Request 2", "curl localhost:8081", /backend [12]/, "It should be the OTHER backend: the default method is round robin (take turns). Others: least_conn (fewest active connections), ip_hash (same client, same backend)."],
    ["Request 3", "curl localhost:8081", /backend [12]/, "Back to the first backend. If one backend dies, NGINX stops sending traffic to it."],
    ["Copy a broken proxy config", "cp /scripts/lab-files/bad.conf /etc/nginx/conf.d/bad.conf", OK, "bad.conf forwards to port 9999, where nothing is running. We create a 502 on purpose."],
    ["Reload", "nginx -s reload", OK, "Applies bad.conf."],
    ["See the error code", "curl -I localhost:8082", /502 Bad Gateway/, "502 = NGINX is fine but could not get a valid answer from the backend. 504 = the backend answered too slowly (timeout)."],
    ["Find the reason in the error log", "tail -2 /var/log/nginx/error.log", /Connection refused/, "connect() failed (111: Connection refused) = nothing listens on that port. Fix the backend or the port number. Interview: '502, what do you check?' error.log first, then is the backend running."],
    ["Copy a routing config", "cp /scripts/lab-files/routes.conf /etc/nginx/conf.d/routes.conf", OK, "routes.conf shows location blocks: a prefix /api/, an exact /health and a default /."],
    ["Reload", "nginx -s reload", OK, "Applies routes.conf."],
    ["Test the health route", "curl localhost:8083/health", /healthy/, "location = /health is an EXACT match. Health checks use a route like this."],
    ["Test the api route", "curl localhost:8083/api/users", /(^|[\r\n])api[\r\n]/, "location /api/ is a prefix match: anything that starts with /api/ lands here."],
    ["Stop NGINX", "nginx -s stop", OK, "Fast shutdown. -s quit finishes current requests first."],
  ]},
  ],
  server: { name: "On a real server (TLS, limits)", note: "Needs a certificate and systemd. Copy-only.", steps: [
    ["Start, reload, restart as a service", "systemctl reload nginx", null, "Use reload for config changes, restart only when needed."],
    ["TLS termination (inside a server block)", "listen 443 ssl; ssl_certificate /etc/ssl/site.crt; ssl_certificate_key /etc/ssl/site.key;", null, "NGINX handles HTTPS and talks plain HTTP to the backend. Put these lines in the server block."],
    ["Redirect http to https", "return 301 https://$host$request_uri;", null, "Put this in a server block that listens on port 80."],
    ["Rate limiting (http block)", "limit_req_zone $binary_remote_addr zone=one:10m rate=10r/s;", null, "Defines a zone: max 10 requests per second per client IP. Then limit_req zone=one; inside a location. Extra requests get 503."],
    ["Pass the real client IP to the app", "proxy_set_header X-Real-IP $remote_addr;", null, "Without it the backend only sees NGINX's address."],
  ]},
  qa: [
    ["What is a reverse proxy?", [["Answer", "A server in front of your apps. Clients talk to it, it forwards to the real servers. Gives TLS, caching, load balancing and one entry point."], ["Forward proxy", "Sits in front of CLIENTS (like a company proxy for outgoing traffic). Opposite direction."]]],
    ["502 vs 504?", [["502 Bad Gateway", "The backend is down, refused the connection or sent garbage. Check error.log and whether the backend runs."], ["504 Gateway Timeout", "The backend is up but too slow. Check backend load or raise proxy_read_timeout."]]],
    ["Reload vs restart?", [["Reload", "Re-reads the config, workers finish old requests, no downtime."], ["Restart", "Stops everything and starts again: brief downtime."]]],
    ["Name the load balancing methods", [["Default", "Round robin (take turns)."], ["Others", "least_conn, ip_hash (sticky by client), weights."]]],
    ["How do you check a config change safely?", [["Answer", "nginx -t, then nginx -s reload. Never reload without testing."]]],
    ["Where do you look when a site is broken?", [["Logs", "/var/log/nginx/error.log and access.log."], ["Also", "Is NGINX running? Is the port listening (ss -tln)? Does the backend answer (curl localhost:PORT)?"]]],
    ["What does location / vs location = /health mean?", [["Prefix", "location /api/ matches everything that starts with /api/."], ["Exact", "location = /health matches only that one path."]]],
  ] },

/* ================================================= 5 · DOCKER ================================================= */
{ id: "t5", name: "5 · Docker (Week 2)", port: 7682, cwd: "/work/lab-docker",
  goal: "Images and containers first, then inspecting and debugging running containers, then your own image, volumes and networks. Runs in the toolbox terminal that talks to Docker Desktop.",
  reset: ["cd /work", "docker rm -f lab-hi lab-web", "docker rmi lab-hello", "docker volume rm lab-vol", "docker network rm lab-net"],
  levels: [
  { key: "l1", name: "Level 1 · Basic", steps: [
    ["Is Docker there?", "docker --version", /Docker version/, "Prints the client version. If later commands hang, the Docker engine (Docker Desktop) is not running."],
    ["Download an image", "docker pull alpine", /alpine/, "An IMAGE is a read-only package: an app and its files. pull downloads it from Docker Hub. alpine is a tiny 5 MB Linux. No tag means :latest."],
    ["List images", "docker images", /alpine/, "Shows repository, tag, id and size of every image on this machine."],
    ["Run a container", "docker run --name lab-hi alpine echo hello", LINE("hello"), "A CONTAINER is a running copy of an image. run = create + start. The container ran echo, then ended because its command finished."],
    ["List running containers", "docker ps", /CONTAINER ID/, "Only RUNNING containers. lab-hi is not listed because it already exited."],
    ["List all containers", "docker ps -a", /lab-hi/, "-a includes stopped containers. Status 'Exited (0)' = finished normally. Interview: 'container exits immediately, why?' Its main command finished or crashed: look at the exit code and docker logs."],
    ["Remove it", "docker rm lab-hi", LINE("lab-hi"), "Deletes a stopped container. The image stays."],
    ["Run a web server in the background", "docker run -d --name lab-web -p 8097:80 nginx:1.27-alpine", /(^|[\r\n])[0-9a-f]{64}/, "-d = detached (background). --name gives it a name. -p 8097:80 = host port 8097 to container port 80. Prints the container id."],
    ["Is it running?", "docker ps", /lab-web/, "Now you see it with its ports and status 'Up'."],
    ["Read its logs", "docker logs lab-web", /start worker process|ready for start up|Configuration complete/, "logs shows what the container printed on stdout and stderr. -f follows live, --tail 20 shows the last 20 lines. First step when a container misbehaves."],
    ["Stop it", "docker stop lab-web", LINE("lab-web"), "Sends SIGTERM (polite), waits 10 seconds, then SIGKILL. docker start lab-web brings the same container back."],
    ["Delete it", "docker rm lab-web", LINE("lab-web"), "Removes the stopped container. docker rm -f does stop and remove in one go."],
  ]},
  { key: "l2", name: "Level 2 · Next level", steps: [
    ["Start a web server again", "docker run -d --name lab-web -p 8097:80 nginx:1.27-alpine", /(^|[\r\n])[0-9a-f]{64}/, "Same command as before. This level inspects a running container."],
    ["Run one command inside it", "docker exec lab-web nginx -v", /nginx\/1\.27/, "exec runs a command inside a RUNNING container. For a shell use docker exec -it lab-web sh (-i keep input open, -t terminal). Type exit to leave."],
    ["Look around inside", "docker exec lab-web ls /etc/nginx", /nginx\.conf/, "The container has its own file system, taken from the image."],
    ["Last log lines", "docker logs --tail 3 lab-web", /(start worker|notice|Configuration|ready)/, "--tail N limits the output. Use it on chatty containers."],
    ["Ask for one fact", "docker inspect lab-web --format '{{.State.Status}}'", /running/, "inspect prints all the details as JSON: ip, mounts, env, restart policy. --format picks one field."],
    ["Check the port mapping", "docker port lab-web", /80\/tcp -> .*8097/, "Shows which host port maps to which container port."],
    ["CPU and memory", "docker stats --no-stream", /lab-web/, "Live usage per container. --no-stream prints once."],
    ["Processes inside", "docker top lab-web", /nginx/, "Like ps for one container."],
    ["Restart it", "docker restart lab-web", LINE("lab-web"), "stop + start. Used after changing something the container reads only at startup."],
    ["Stop and remove in one go", "docker rm -f lab-web", LINE("lab-web"), "-f forces removal of a running container."],
  ]},
  { key: "l3", name: "Level 3 · Medium", steps: [
    ["Read the sample Dockerfile", "cat Dockerfile", /FROM alpine/, "FROM = base image. RUN = a command executed while BUILDING (saved as a layer). CMD = the default command when a container STARTS. Mixing up RUN and CMD is the most common beginner mistake."],
    ["Build your image", "docker build -t lab-hello .", /^(?![\s\S]*ERROR)[\s\S]*(naming to|writing image|DONE)/, "build reads the Dockerfile in the folder (the dot = build context). -t names the image."],
    ["Run your image", "docker run --rm lab-hello", /(^|[\r\n])hello from my image/, "--rm deletes the container when it exits, so nothing piles up."],
    ["Build again", "docker build -t lab-hello .", /CACHED/, "Nothing changed, so every layer comes from the cache. If you change one line, that layer and all layers AFTER it rebuild: put rarely changing steps first."],
    ["See the layers", "docker history lab-hello", /CMD/, "Every Dockerfile instruction is one layer. Smaller and fewer layers = smaller image."],
    ["Create a volume", "docker volume create lab-vol", LINE("lab-vol"), "A volume keeps data OUTSIDE the container, so it survives container deletion. Files written inside a container are lost when it is removed."],
    ["Write a file into the volume", "docker run --rm -v lab-vol:/data alpine touch /data/f.txt", OK, "-v lab-vol:/data mounts the volume at /data. The container is deleted afterwards."],
    ["Read it from a NEW container", "docker run --rm -v lab-vol:/data alpine ls /data", /f\.txt/, "The file is still there: that is persistence. Databases must always use a volume."],
    ["Create a network", "docker network create lab-net", OK, "A user-defined network gives containers DNS: they can reach each other by NAME."],
    ["Start a web container on it", "docker run -d --name lab-web --network lab-net nginx:1.27-alpine", /(^|[\r\n])[0-9a-f]{64}/, "No -p needed: other containers on the same network reach it directly."],
    ["Reach it by name from another container", "docker run --rm --network lab-net alpine ping -c 1 lab-web", /1 packets received/, "The name lab-web resolved by itself. This is how Compose services find each other (api talks to db by name)."],
    ["Clean up the container", "docker rm -f lab-web", LINE("lab-web"), "Remove the running container."],
    ["Clean up the image", "docker rmi lab-hello", OK, "rmi removes an image. docker system prune removes all unused things (ask first!)."],
    ["Clean up the volume and network", "docker volume rm lab-vol", LINE("lab-vol"), "Volumes are never deleted automatically."],
    ["Remove the network", "docker network rm lab-net", LINE("lab-net"), "Everything created by this topic is now gone."],
  ]},
  ],
  server: { name: "Interactive and more", note: "These need a live terminal session. Copy and run them in the terminal on the right.", steps: [
    ["Open a shell inside a container", "docker exec -it lab-web sh", null, "-it = interactive terminal. Type exit to leave. The container keeps running."],
    ["Run a throwaway container with a shell", "docker run -it --rm alpine sh", null, "--rm deletes it on exit. Perfect for trying commands safely."],
    ["Free disk space", "docker system prune", null, "Removes stopped containers, unused networks and dangling images. It asks first."],
    ["See disk used by Docker", "docker system df", null, "Images, containers, volumes and build cache, and how much can be reclaimed."],
  ]},
  qa: [
    ["Image vs container?", [["Image", "Read-only package: app + files. Built once."], ["Container", "A running (or stopped) instance of an image. You can start many from one image."]]],
    ["A container exits immediately. Why?", [["Reason", "Its main process (PID 1) ended or crashed. A web server stays up because it never ends."], ["Check", "docker ps -a (exit code), then docker logs NAME."]]],
    ["CMD vs ENTRYPOINT?", [["ENTRYPOINT", "The fixed program."], ["CMD", "The default arguments. docker run IMAGE args replaces CMD, not ENTRYPOINT."]]],
    ["COPY vs ADD?", [["Rule", "Use COPY. ADD can also download URLs and unpack archives, which surprises people."]]],
    ["Volume vs bind mount?", [["Volume", "Managed by Docker, best for databases and persistent data."], ["Bind mount", "A host folder mapped into the container, good for source code in development."]]],
    ["EXPOSE vs -p?", [["EXPOSE", "Documentation only: the image uses this port."], ["-p 8080:80", "Actually publishes the port on the host."]]],
    ["How do you make an image smaller?", [["Ideas", "Small base (alpine), multi-stage builds, fewer layers, .dockerignore, no build tools in the final image."]]],
    ["How do two containers talk to each other?", [["Answer", "Put them on the same user-defined network and use the container name as the host name (Docker's built-in DNS)."]]],
  ] },

/* ================================================= 6 · GIT + CI/CD ================================================= */
{ id: "t6", name: "6 · Git and CI/CD (Week 3)", port: 7682, cwd: "~/lab",
  goal: "Git first (commit, branch, merge), then read a real GitHub Actions workflow file and ask it questions. The pipeline itself runs on GitHub, so the last tab is copy-only.",
  reset: ["cd ~", "rm -rf ~/lab"],
  levels: [
  { key: "l1", name: "Level 1 · Basic", steps: [
    ["Make a practice folder", "mkdir -p ~/lab", OK, "All git practice stays inside ~/lab."],
    ["Go into it", "cd ~/lab", OK, "cd = change directory."],
    ["Create a repository", "git init -b main app", /Initialized empty Git repository/, "git init turns a folder into a repository: it adds a hidden .git folder that stores the whole history. -b main names the first branch main."],
    ["Go into the repository", "cd app", OK, "Everything from here on happens inside app."],
    ["Tell git who you are", "git config user.name 'Lab User'", OK, "Every commit records an author. Without --global this applies to this repository only."],
    ["And your email", "git config user.email 'lab@example.com'", OK, "Use your real email on a real project: GitHub matches commits to your account with it."],
    ["Turn off the pager", "git config core.pager cat", OK, "By default git opens long output in a pager (press q to quit). cat just prints it, which is easier here."],
    ["Create a file", "echo hello > app.txt", OK, "A new file. Git does not track it yet."],
    ["Check the state", "git status", /Untracked files/, "git status is the command you will type most. 'Untracked' = git sees the file but is not watching it."],
    ["Stage the file", "git add app.txt", OK, "git add puts the change in the staging area: the list of changes that go into the next commit. git add . stages everything."],
    ["Save a commit", "git commit -m 'first commit'", /1 file changed/, "A commit is a snapshot with a message. -m gives the message. Write what changed and why."],
    ["See the history", "git log --oneline", /first commit/, "One line per commit: short id and message. HEAD is where you are now."],
    ["Check again", "git status", /nothing to commit/, "'nothing to commit, working tree clean' = everything is saved."],
  ]},
  { key: "l2", name: "Level 2 · Next level", cwd: "~/lab/app", needs: "l1", steps: [
    ["Start a new branch", "git switch -c feature", /Switched to a new branch 'feature'/, "A branch is a separate line of work. -c creates it and switches. Real teams make one branch per change and open a pull request."],
    ["Change the file", "echo change >> app.txt", OK, ">> adds a line at the end."],
    ["See what changed", "git diff", /\+change/, "git diff shows changes that are NOT staged yet. + lines were added, - lines removed. git diff --staged shows what is staged."],
    ["Stage it", "git add app.txt", OK, "Staging again."],
    ["Commit it", "git commit -m 'add change'", /1 file changed/, "The commit goes on the feature branch only."],
    ["Look at the history", "git log --oneline", /add change/, "Two commits now. The newest is on top."],
    ["Go back to main", "git switch main", /Switched to branch 'main'/, "main does not have the change yet."],
    ["Merge the branch", "git merge feature", /Fast-forward/, "merge brings the feature commits into main. Fast-forward = main had no new commits, so git just moves the pointer. Otherwise git makes a merge commit and conflicts may appear."],
    ["List branches", "git branch", /\* main/, "The star marks the branch you are on."],
    ["Delete the finished branch", "git branch -d feature", /Deleted branch feature/, "-d only deletes if it is merged. -D forces it."],
  ]},
  { key: "l3", name: "Level 3 · Medium", cwd: "~/lab/app", needs: "l1", steps: [
    ["Ignore log files", "echo '*.log' > .gitignore", OK, ".gitignore lists files git must never track: logs, build output, secrets like .env."],
    ["Create a log file", "touch debug.log", OK, "This file matches the pattern, so git will ignore it."],
    ["Check what git sees", "git status --short", /^(?![\s\S]*debug\.log)[\s\S]*\?\? \.gitignore/, "--short = one line per file. ?? = untracked. debug.log is not listed because it is ignored."],
    ["Make the workflow folder", "mkdir -p .github/workflows", OK, "GitHub runs every YAML file in .github/workflows. The folder name is fixed."],
    ["Copy a sample workflow", "cp /work/lab-ci/ci.yml .github/workflows/ci.yml", OK, "A small CI pipeline: on every push to main (and every pull request) it checks out the code, runs tests and builds an image."],
    ["Read it", "cat .github/workflows/ci.yml", /runs-on: ubuntu-latest/, "name = the workflow name. on = triggers. jobs = parallel groups of work. runs-on = the machine type. steps = commands in order. uses = a ready-made action, run = a shell command."],
    ["Ask it: when does it run?", "yq '.on' .github/workflows/ci.yml", /pull_request/, "yq reads YAML like jq reads JSON. The triggers are push to main and any pull request."],
    ["Ask it: what are the steps?", "yq '.jobs.build.steps[].name' .github/workflows/ci.yml", /Checkout code[\s\S]*Run tests/, "The steps run top to bottom. If one fails, the job stops and the pull request shows a red cross."],
    ["Stage everything", "git add .", OK, "Stages the new files. debug.log is skipped."],
    ["Commit the workflow", "git commit -m 'add CI workflow'", /2 files changed/, "Pushing this file to GitHub is all it takes to start the pipeline."],
    ["See the history", "git log --oneline", /add CI workflow/, "Your pipeline is now versioned like any other code."],
    ["Tag a release", "git tag v1.0", OK, "A tag is a permanent name for a commit, used for releases. A workflow can trigger on tags."],
    ["List tags", "git tag", LINE("v1\\.0"), "Tags follow semantic versioning: v1.0.0 (major.minor.patch)."],
  ]},
  ],
  server: { name: "On GitHub (copy only)", note: "These live in the workflow file or run on GitHub. Copy them into ci.yml when you want to try them.", steps: [
    ["Run on a schedule or by hand", "on: { workflow_dispatch: {}, schedule: [{ cron: '0 2 * * *' }] }", null, "workflow_dispatch adds a 'Run workflow' button. schedule uses cron syntax (UTC)."],
    ["Run the job on several versions (matrix)", "strategy: { matrix: { node: [18, 20] } }", null, "One job definition runs once per value, in parallel. Use ${{ matrix.node }} inside the steps."],
    ["Use a secret", "env: { TOKEN: '${{ secrets.MY_TOKEN }}' }", null, "Secrets are set in the repository settings. They are masked in the logs. Never print them or commit them."],
    ["Cache dependencies", "uses: actions/cache@v4", null, "Saves a folder (node_modules, ~/.m2) between runs so builds are faster. The key decides when the cache is reused."],
    ["Keep a build result", "uses: actions/upload-artifact@v4", null, "Saves files (reports, binaries) so you can download them or use them in a later job."],
    ["Log in to AWS without a stored key (OIDC)", "permissions: { id-token: write, contents: read }", null, "OIDC lets GitHub prove its identity to the cloud and get a short-lived token. No long-lived access keys in your secrets."],
    ["Run one job after another", "needs: build", null, "By default jobs run in parallel. needs makes a job wait for another one."],
  ]},
  qa: [
    ["Workflow, job, step: what is the difference?", [["Workflow", "One YAML file. Starts on an event (push, pull request, schedule)."], ["Job", "A group of steps that runs on one machine. Jobs run in parallel unless one needs another."], ["Step", "One command (run) or one ready-made action (uses)."]]],
    ["What is CI and what is CD?", [["CI", "Continuous Integration: every push is built and tested automatically, so broken code is found early."], ["CD", "Continuous Delivery/Deployment: a tested build is released automatically (delivery stops at a manual approval, deployment goes all the way)."]]],
    ["How do you keep secrets safe in a pipeline?", [["Answer", "Store them as encrypted secrets, never in the repository. Prefer OIDC (short-lived tokens) over long-lived keys. Give each job the least permission it needs."]]],
    ["What is a matrix build?", [["Answer", "One job that runs several times with different values (OS, language version), in parallel."]]],
    ["How do you make a pipeline faster?", [["Ideas", "Cache dependencies, run independent jobs in parallel, build only what changed, use a smaller base image."]]],
    ["Merge vs rebase?", [["Merge", "Keeps all history and adds a merge commit."], ["Rebase", "Replays your commits on top of the target for a straight, clean history. Never rebase commits that others already use."]]],
    ["How do you undo things in git?", [["Not committed", "git restore FILE discards changes to a file."], ["Committed", "git revert COMMIT makes a new commit that undoes it (safe for shared branches). git reset moves the branch back (rewrites history)."]]],
  ] },

/* ================================================= 7 · TERRAFORM ================================================= */
{ id: "t7", name: "7 · Terraform (Week 3)", port: 7682, cwd: "~/tf",
  goal: "Write, plan and apply infrastructure as code. The lab uses Terraform's built-in terraform_data resource, so it needs no cloud account and no internet: same workflow, nothing to pay for.",
  reset: ["cd ~", "rm -rf ~/tf ~/tf2"],
  levels: [
  { key: "l1", name: "Level 1 · Basic", steps: [
    ["Make a project folder", "mkdir -p ~/tf", OK, "A Terraform project is just a folder of .tf files."],
    ["Go into it", "cd ~/tf", OK, "Terraform always works on the files in the current folder."],
    ["Which version?", "terraform version", /Terraform v\d/, "Version of the tool. Teams pin it, because state files from a newer version cannot be read by an older one."],
    ["Copy a small configuration", "cp /work/lab-tf/basic.tf main.tf", OK, "main.tf is the usual name for the main file."],
    ["Read it", "cat main.tf", /terraform_data/, "variable = an input with a default. resource = a thing Terraform manages (type, then your name). output = a value printed at the end. Cloud resources look the same, for example aws_s3_bucket."],
    ["Initialise", "terraform init", /Terraform has been successfully initialized/, "init downloads providers and sets up the backend. Run it first in every new folder, and again after you add a provider or module."],
    ["Check the syntax", "terraform validate", /Success! The configuration is valid/, "validate checks the files for mistakes without touching anything."],
    ["See the plan", "terraform plan", /Plan: 1 to add, 0 to change, 0 to destroy/, "plan compares your code with reality and shows what WOULD change. + create, ~ change, - destroy. Always read it before applying."],
    ["Apply it", "terraform apply -auto-approve", /Apply complete! Resources: 1 added/, "apply makes the change. -auto-approve skips the yes/no question: fine in a lab, in real life review the plan first."],
    ["Show the outputs", "terraform output", /greeting = "Hello, DevOps"/, "Outputs are the values you want to read afterwards: an IP address, a URL."],
    ["List what Terraform manages", "terraform state list", /terraform_data\.hello/, "The state file is Terraform's memory of what it created. Without it Terraform would not know what exists."],
  ]},
  { key: "l2", name: "Level 2 · Next level", needs: "l1", steps: [
    ["Plan again", "terraform plan", /No changes/, "Nothing changed, so nothing to do. This is idempotence: applying twice gives the same result."],
    ["Change an input variable", "terraform apply -auto-approve -var name=Asha", /Apply complete!/, "-var overrides a variable for one run. Real projects use a terraform.tfvars file instead."],
    ["Read the new output", "terraform output greeting", /Hello, Asha/, "Naming the output prints just its value, handy in scripts."],
    ["Format the code", "terraform fmt", OK, "fmt fixes indentation and spacing. It prints the names of files it changed. No output = already tidy. CI pipelines run terraform fmt -check."],
    ["Check the syntax again", "terraform validate", /Success!/, "Run validate and fmt before every commit."],
    ["Preview another change", "terraform plan -var name=Ravi", /Plan:/, "A plan is only a preview. Nothing changes until apply."],
    ["Look at the state file", "ls", /terraform\.tfstate/, "terraform.tfstate holds the real values. It can contain secrets, so never commit it to git. Teams keep it in a remote backend (S3 + DynamoDB lock, or Azure Storage) so two people cannot apply at once."],
    ["Inspect one resource", "terraform state show terraform_data.hello", /terraform_data\.hello/, "Shows everything Terraform knows about one resource."],
    ["Destroy everything", "terraform destroy -auto-approve", /Destroy complete! Resources: 1 destroyed/, "destroy removes every resource in the state. In real life, be very careful."],
    ["Check that it is empty", "terraform state list", OK, "No output = nothing is managed any more."],
  ]},
  { key: "l3", name: "Level 3 · Medium", cwd: "~/tf2", steps: [
    ["Make a second project", "mkdir -p ~/tf2", OK, "A fresh folder for a project that uses a module."],
    ["Go into it", "cd ~/tf2", OK, "cd = change directory."],
    ["Copy the project", "cp -r /work/lab-tf/mod/. .", OK, "Copies main.tf and a modules folder. The dot at the end means 'into this folder'."],
    ["See the layout", "ls", /modules/, "A module is just a folder with .tf files that you reuse, like a function."],
    ["Read the root file", "cat main.tf", /module "greeter"/, "The module block calls the module: source = where it is, names = the input it needs."],
    ["Read the module", "cat modules/greeter/main.tf", /for_each/, "for_each creates one resource per item in the list. count = N is the simpler cousin. Prefer for_each when items have names, because removing one does not renumber the others."],
    ["Initialise", "terraform init", /Terraform has been successfully initialized/, "init also loads the modules this time."],
    ["Plan", "terraform plan", /Plan: 3 to add/, "Three names in the list = three resources."],
    ["Apply", "terraform apply -auto-approve", /Apply complete! Resources: 3 added/, "All three are created."],
    ["Show the output", "terraform output", /hi asha/, "The module returned a list; the root file printed it."],
    ["See the addresses", "terraform state list", /module\.greeter\.terraform_data\.msg\["asha"\]/, "module.NAME.TYPE.NAME[key] is the full address of a resource inside a module."],
    ["Clean up", "terraform destroy -auto-approve", /Destroy complete! Resources: 3 destroyed/, "Removes the three resources."],
  ]},
  ],
  server: { name: "With a real cloud (copy only)", note: "These need a cloud account. Copy them when you practise on a KodeKloud AWS or Azure playground.", steps: [
    ["Store state remotely with locking (AWS)", "backend \"s3\" { bucket = \"my-state\" key = \"app/terraform.tfstate\" region = \"us-east-1\" dynamodb_table = \"tf-lock\" }", null, "State goes into an S3 bucket and DynamoDB blocks two people from applying at the same time. Azure uses a storage account with blob lease locking."],
    ["Move local state to the backend", "terraform init -migrate-state", null, "After adding a backend block, this copies your existing state into it."],
    ["A real resource", "resource \"aws_s3_bucket\" \"logs\" { bucket = \"my-unique-logs-bucket\" }", null, "Same shape as the lab resource. The provider (aws) talks to the cloud API."],
    ["Bring an existing resource under Terraform", "terraform import aws_s3_bucket.logs my-unique-logs-bucket", null, "import adds a resource that was created by hand to the state. You still have to write the matching code."],
    ["Run it in a pipeline", "terraform plan -out=tfplan", null, "Save the plan in CI, show it on the pull request, and apply that exact plan after approval: terraform apply tfplan."],
  ]},
  qa: [
    ["What is the Terraform state and why is it important?", [["Answer", "The file where Terraform records what it created. It maps your code to real resources. Lose it and Terraform no longer knows what exists."], ["Teams", "Keep it in a remote backend with locking, encrypted, never in git."]]],
    ["terraform plan vs apply?", [["plan", "Preview only. Compares code, state and reality."], ["apply", "Makes the changes. In CI you apply the saved plan after approval."]]],
    ["What is drift and how do you handle it?", [["Drift", "Someone changed the real infrastructure by hand, so it no longer matches the code."], ["Fix", "terraform plan shows the difference. Apply to put it back, or update the code to match."]]],
    ["count vs for_each?", [["count", "N copies, addressed by number (0, 1, 2). Removing item 0 shifts the others."], ["for_each", "One per key in a map or set, addressed by name. Safer for changes."]]],
    ["What is a module?", [["Answer", "A reusable folder of Terraform code with inputs (variables) and outputs. Used to avoid copy and paste, for example one VPC module for every environment."]]],
    ["How do you handle secrets?", [["Answer", "Mark variables sensitive = true, pass them from environment variables or a secret manager, and keep the state encrypted. They still end up in state, so protect the state."]]],
    ["Terraform vs Ansible?", [["Terraform", "Creates infrastructure (servers, networks). Declarative, keeps state."], ["Ansible", "Configures what runs ON the servers (packages, files). Usually no state."]]],
  ] },

/* ================================================= 8 · CLOUD ================================================= */
{ id: "t8", name: "8 · Cloud AWS / Azure (Week 3)", port: 7682, cwd: "~",
  goal: "Cloud basics you are asked about: who am I, storage, servers, networks and permissions. There is no cloud account in the lab, so the commands are copy-only for a KodeKloud playground. The Q&A tab is the part to learn.",
  reset: [],
  levels: [
  { key: "l1", name: "Level 1 · Basic", copyOnly: true, note: "Copy-only: run these in a KodeKloud AWS playground (or your own account).", steps: [
    ["Who am I? (AWS)", "aws sts get-caller-identity", null, "Shows the account number and the user or role you are using. First command when something says 'access denied'."],
    ["Who am I? (Azure)", "az account show", null, "Shows the subscription and tenant. az login signs you in."],
    ["List storage buckets (AWS S3)", "aws s3 ls", null, "S3 = object storage: files in buckets. Cheap, durable, used for backups, logs, websites and Terraform state."],
    ["Upload a file to S3", "aws s3 cp notes.txt s3://my-bucket/", null, "cp copies between local and S3. aws s3 sync syncs whole folders."],
    ["List servers (AWS EC2)", "aws ec2 describe-instances --query 'Reservations[].Instances[].InstanceId'", null, "EC2 = virtual servers. --query filters the JSON output."],
    ["List resource groups (Azure)", "az group list -o table", null, "A resource group is a folder for related resources. -o table = readable output."],
    ["List VMs (Azure)", "az vm list -o table", null, "Azure virtual machines."],
  ]},
  { key: "l2", name: "Level 2 · Next level", copyOnly: true, note: "Copy-only: identity and networking.", steps: [
    ["List IAM users", "aws iam list-users", null, "IAM = who may do what. A USER is a person, a ROLE is an identity that services or people assume temporarily. Prefer roles."],
    ["List IAM roles", "aws iam list-roles", null, "Roles hold permissions through policies and give short-lived credentials."],
    ["List VPCs", "aws ec2 describe-vpcs", null, "A VPC is your private network in the cloud, with its own IP range (CIDR, for example 10.0.0.0/16)."],
    ["List subnets", "aws ec2 describe-subnets", null, "Subnets split the VPC. Public subnet = has a route to an internet gateway. Private subnet = no direct internet, uses a NAT gateway to go out."],
    ["List security groups", "aws ec2 describe-security-groups", null, "A security group is a firewall around a server. Stateful: if a request is allowed in, the reply is allowed out."],
    ["List Azure networks", "az network vnet list -o table", null, "VNet = Azure's VPC. NSG = network security group, the firewall."],
    ["List Azure role assignments", "az role assignment list -o table", null, "Azure RBAC: who has which role on which scope."],
  ]},
  { key: "l3", name: "Level 3 · Medium", copyOnly: true, note: "Copy-only: containers, logs and keyless login.", steps: [
    ["Log in to the container registry (AWS ECR)", "aws ecr get-login-password", null, "ECR stores your Docker images. The password is piped to docker login. Azure's version is ACR: az acr login --name NAME."],
    ["Read application logs (CloudWatch)", "aws logs tail /aws/lambda/my-function --follow", null, "CloudWatch Logs collects logs and metrics. Azure Monitor is the equivalent."],
    ["List alarms", "aws cloudwatch describe-alarms", null, "Alarms notify you when a metric (CPU, errors) crosses a limit."],
    ["Assume a role", "aws sts assume-role --role-arn ARN --role-session-name lab", null, "Returns temporary keys. This is the safe way to get higher access for a short time."],
    ["Keyless login from GitHub (idea)", "aws-actions/configure-aws-credentials with role-to-assume", null, "A GitHub workflow proves who it is with OIDC and assumes a role. No access keys are stored."],
  ]},
  ],
  qa: [
    ["What is IAM and what is least privilege?", [["IAM", "The service that controls who (users, roles) may do what (policies) on which resources."], ["Least privilege", "Give only the permissions needed for the job, nothing more. Start with none and add."]]],
    ["IAM user vs role?", [["User", "A long-lived identity for a person, with keys or a password."], ["Role", "A temporary identity assumed by a person, service or pipeline. No stored keys. Preferred."]]],
    ["Public vs private subnet?", [["Public", "Has a route to an internet gateway. Load balancers and bastion hosts live here."], ["Private", "No inbound internet. Apps and databases live here and use a NAT gateway for outbound traffic."]]],
    ["What is a NAT gateway?", [["Answer", "Lets servers in a private subnet reach the internet (updates, APIs) without the internet being able to reach them."]]],
    ["Security group vs network ACL?", [["Security group", "Firewall on the server. Stateful. Allow rules only."], ["Network ACL", "Firewall on the subnet. Stateless: you must allow replies too. Allow and deny rules."]]],
    ["Region vs availability zone?", [["Region", "A geographic area (Mumbai, Frankfurt)."], ["Availability zone", "One or more separate data centres inside a region. Spread servers across zones to survive a failure."]]],
    ["EC2 vs Lambda (VM vs serverless)?", [["EC2", "You run a server and pay while it is on. Full control."], ["Lambda", "You upload a function, the cloud runs it on demand. Pay per run. Good for short, event-driven work."]]],
    ["How does a pipeline log in to the cloud safely?", [["Answer", "OIDC: the pipeline gets a short-lived token and assumes a role. No long-lived access keys in secrets."]]],
  ] },
];
